"""Git and linked-worktree state for bounded task runs."""

from __future__ import annotations

import os
import re
import subprocess
import sys
from collections.abc import Callable
from pathlib import Path
from typing import Any, Mapping, Sequence


def _load_repo_runtime_bootstrap():
    pathlib, sys = __import__("pathlib"), __import__("sys")
    marker = ("scripts", "adapter_lib.py")
    parents = pathlib.Path(__file__).resolve().parents
    root = next((p for p in parents if p.joinpath(*marker).is_file()), None)
    if root is not None and str(root) not in sys.path:
        sys.path.insert(0, str(root))


_load_repo_runtime_bootstrap()

from scripts.core.git_checkout import head_oid_from_files as _head_sha_from_checkout  # noqa: E402
from scripts.core.git_checkout import (  # noqa: E402
    identity_from_files,
    layout_from_files,
    worktree_root_from_files,
)
from scripts.core.git_status_snapshot import GitStatusError  # noqa: E402
from scripts.worktree.checkout_view import (  # noqa: E402
    CheckoutView,
    GitCheckout,
    moment_from_status,
)

try:
    from scripts.core.subprocess_guard import run_process
except ImportError:  # flat layout: the script dir is on sys.path, the repo root is not
    _scripts_dir = next(
        ancestor / "scripts"
        for ancestor in Path(__file__).resolve().parents
        if (ancestor / "scripts" / "core" / "subprocess_guard.py").is_file()
    )
    if str(_scripts_dir) not in sys.path:
        sys.path.insert(0, str(_scripts_dir))
    from subprocess_guard import run_process
from scripts.task_run.task_run_contract import (  # noqa: E402
    _BRANCH_RE,
    _GIT_DISCOVERY_ENV,
    FAIL,
    PASS,
    TaskRunError,
)

WIP_CANDIDATE_COMMIT_MESSAGE = "task-run: WIP candidate — interrupted mid-edit — state unknown"
PERSIST_CANDIDATE_COMMIT_MESSAGE = "task-run: persist validated candidate onto the lane branch"


def _git_env() -> dict[str, str]:
    return {key: value for key, value in os.environ.items() if key not in _GIT_DISCOVERY_ENV}


def _git(repo_root: Path, *args: str) -> subprocess.CompletedProcess[str]:
    return run_process(["git", *args], cwd=repo_root, env=_git_env(), timeout_seconds=None)


def _git_output(repo_root: Path, *args: str) -> str:
    if args == ("rev-parse", "HEAD"):
        oid = _head_sha_from_checkout(repo_root)
        if oid:
            return oid
    result = _git(repo_root, *args)
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip() or "git command failed"
        raise TaskRunError(f"git {' '.join(args)} failed: {detail}")
    return result.stdout


def _repo_snapshot(repo_root: Path) -> dict[str, Any]:
    """Read immutable repository identity and topology from checkout files.

    The task lifecycle needs the same four scalar facts at its input boundary:
    the worktree root, the shared administration directory, the checkout's
    administration directory, and ``HEAD``.  Ordinary layouts already state
    them; ``rev-parse`` remains the fallback for redirected or packed layouts.
    """
    requested = repo_root.expanduser().resolve()
    identity = identity_from_files(requested)
    if identity is not None:
        if identity.repo_root != requested:
            raise TaskRunError(
                f"--repo-root must be the Git worktree root, not a subdirectory: {requested}"
            )
        return {
            "repo_root": identity.repo_root,
            "git_common_dir": identity.common_dir,
            "git_dir": identity.git_dir,
            "head": identity.head_oid,
        }
    values = _git_output(
        requested,
        "rev-parse",
        "--show-toplevel",
        "--git-common-dir",
        "--git-dir",
        "HEAD",
    ).splitlines()
    if len(values) != 4:
        raise TaskRunError("git rev-parse returned an incomplete repository snapshot")
    discovered = Path(values[0]).resolve()
    common = Path(values[1])
    if not common.is_absolute():
        common = discovered / common
    git_dir = Path(values[2])
    if not git_dir.is_absolute():
        git_dir = discovered / git_dir
    common = common.resolve()
    git_dir = git_dir.resolve()
    if discovered != requested:
        raise TaskRunError(
            f"--repo-root must be the Git worktree root, not a subdirectory: {requested}"
        )
    if not common.is_dir():
        raise TaskRunError(f"Git common directory is not a directory: {common}")
    if not git_dir.is_dir():
        raise TaskRunError(f"Git directory is not a directory: {git_dir}")
    return {
        "repo_root": discovered,
        "git_common_dir": common,
        "git_dir": git_dir,
        "head": values[3].strip(),
    }


def _partition_addable_paths(
    repo_root: Path, paths: Sequence[str], git_run: Callable[..., Any]
) -> tuple[list[str], list[str]]:
    """Split checkpoint paths into addable ones and already-staged deletions (#826).

    Re-adding an already-staged deletion fails (`pathspec did not match`),
    so a path absent from both the worktree and the index but present in
    HEAD is skipped: its deletion is already staged and the commit pathspec
    below carries it. Anything else stages normally, preserving the typed
    refusal for genuinely unknown paths.
    """
    tracked = set()
    if paths:
        listed = git_run(repo_root, "ls-files", "--", *paths)
        if listed.returncode == 0:
            tracked = set(listed.stdout.splitlines())
    addable: list[str] = []
    staged: list[str] = []
    for path in paths:
        if os.path.lexists(repo_root / path) or path in tracked:
            addable.append(path)
        elif git_run(repo_root, "cat-file", "-e", f"HEAD:{path}").returncode == 0:
            staged.append(path)
        else:
            addable.append(path)
    return addable, staged


def _commit_lane_snapshot(
    repo_root: Path,
    *,
    message: str,
    allow_empty: bool = False,
    paths: Sequence[str] | None = None,
    git: Callable[..., Any] | None = None,
    git_output: Callable[..., str] | None = None,
) -> dict[str, Any]:
    """Commit lane output onto the current branch.

    ``paths`` stages and commits only the named repository-relative paths: the
    commit itself carries the pathspec, so content the lane staged outside the
    scope stays staged and out of the commit. ``None`` keeps the historical
    stage-everything shape for callers with no scope classification to reuse;
    the completed-lane persistence path passes the scope verdict's admitted
    set instead of staging everything.
    """
    git_run = git if git is not None else _git
    read_output = git_output if git_output is not None else _git_output
    if paths is None:
        staged = git_run(repo_root, "add", "--all", "--", ".")
    else:
        addable, _already_staged = _partition_addable_paths(repo_root, list(paths), git_run)
        staged = git_run(repo_root, "add", "--", *addable) if addable else None
    if staged is not None and staged.returncode != 0:
        detail = str(
            getattr(staged, "stderr", None) or getattr(staged, "stdout", None) or "git add failed"
        ).strip()
        raise TaskRunError(f"git add failed: {detail}")
    commit_cmd = ["commit"]
    if allow_empty:
        commit_cmd.append("--allow-empty")
    commit_cmd.extend(["--no-verify", "--message", message])
    if paths is not None:
        commit_cmd.extend(["--", *paths])
    committed = git_run(
        repo_root,
        "-c",
        "user.email=charness-task-run@localhost",
        "-c",
        "user.name=charness task run",
        *commit_cmd,
    )
    if committed.returncode != 0:
        detail = str(
            getattr(committed, "stderr", None)
            or getattr(committed, "stdout", None)
            or "git commit failed"
        ).strip()
        raise TaskRunError(f"git commit failed: {detail}")
    sha = _head_sha_from_checkout(repo_root) if git is None else None
    if not sha:
        sha = read_output(repo_root, "rev-parse", "HEAD").strip()
    return {
        "status": "committed",
        "sha": sha,
        "message": message,
        "correctness_verified": False,
    }


def _commit_wip_candidate(repo_root: Path, paths: Sequence[str]) -> dict[str, Any]:
    """Checkpoint declared-scope lane output as an explicitly unverified WIP.

    Only the named paths are staged and committed, and the commit is never
    empty: a caller with zero scoped changes must skip the commit instead of
    recording one (#816). Content staged outside the scope stays staged and
    out of the commit. An empty stage fails the commit rather than recording
    nothing.
    """
    return _commit_lane_snapshot(
        repo_root,
        message=WIP_CANDIDATE_COMMIT_MESSAGE,
        paths=list(paths),
    )


_CONFLICT_MARKER_LINE = re.compile(r"^([^:\n]+):\d+:.*conflict[ -]marker", re.IGNORECASE)


def _conflict_marker_paths(repo_root: Path) -> list[str]:
    """Paths whose staged or unstaged changes still contain merge markers (#877).

    Staging a conflicted file clears its unmerged index entries even when the
    markers remain, so the unmerged listing alone cannot prove a merge is
    resolved. `git diff --check` reports the leftover markers; only those
    lines count, never ordinary whitespace findings.
    """
    found: set[str] = set()
    for args in (["diff", "--check"], ["diff", "--cached", "--check"]):
        proc = _git(repo_root, *args)
        for line in (proc.stdout + proc.stderr).splitlines():
            match = _CONFLICT_MARKER_LINE.match(line)
            if match:
                found.add(match.group(1))
    return sorted(found)


def _merge_state(repo_root: Path) -> tuple[bool, list[str]]:
    """Report an in-progress merge and its still-unresolved paths (#877)."""
    merging = _git(repo_root, "rev-parse", "--verify", "--quiet", "MERGE_HEAD").returncode == 0
    if not merging:
        return False, []
    unmerged = _git_output(repo_root, "diff", "--name-only", "--diff-filter=U")
    unmerged_paths = {line.strip() for line in unmerged.splitlines() if line.strip()}
    return True, sorted(unmerged_paths | set(_conflict_marker_paths(repo_root)))


def _commit_merge_candidate(repo_root: Path) -> dict[str, Any]:
    """Checkpoint a fully-resolved in-progress merge as the WIP candidate.

    Git refuses a partial commit during a merge, so the merge commits whole:
    the caller must have verified no unmerged paths remain. The WIP message
    still marks the result explicitly unverified.
    """
    return _commit_lane_snapshot(
        repo_root,
        message=WIP_CANDIDATE_COMMIT_MESSAGE,
        paths=None,
    )


def _tip_candidate(head_sha: str) -> dict[str, Any]:
    """Name a clean-tree branch tip as the WIP candidate (#877).

    The lane committed its own work before it ended abnormally, so there is
    nothing left to commit: the tip already carries the candidate. The shape
    matches a checkpoint commit; only the commit step is skipped.
    """
    return {"status": "committed", "sha": head_sha, "message": WIP_CANDIDATE_COMMIT_MESSAGE, "correctness_verified": False}


def _require_git_root(repo_root: Path) -> Path:
    repo_root = repo_root.expanduser().resolve()
    discovered = worktree_root_from_files(repo_root)
    if discovered is None:
        discovered = Path(_git_output(repo_root, "rev-parse", "--show-toplevel").strip()).resolve()
    if discovered != repo_root:
        raise TaskRunError(
            f"--repo-root must be the Git worktree root, not a subdirectory: {repo_root}"
        )
    return repo_root


def _resolve_base_sha(repo_root: Path, base: str) -> str:
    if not base.strip():
        raise TaskRunError("--base is required and must resolve to a commit")
    result = _git(
        repo_root,
        "rev-parse",
        "--verify",
        "--quiet",
        "--end-of-options",
        f"{base}^{{commit}}",
    )
    sha = result.stdout.strip()
    if result.returncode != 0 or not re.fullmatch(r"[0-9a-fA-F]{40,64}", sha):
        raise TaskRunError(result.stderr.strip() or f"ref is not resolvable: {base}")
    return sha


def _git_common_dir(repo_root: Path) -> Path:
    """Writable Git administration root required for a linked worktree."""
    layout = layout_from_files(repo_root)
    if layout is not None:
        return layout.common_dir
    value = _git_output(repo_root, "rev-parse", "--git-common-dir").strip()
    common = Path(value)
    if not common.is_absolute():
        common = repo_root / common
    resolved = common.resolve()
    if not resolved.is_dir():
        raise TaskRunError(f"Git common directory is not a directory: {resolved}")
    return resolved


def _git_dir(repo_root: Path) -> Path:
    """Return the checkout-specific Git administration directory."""
    layout = layout_from_files(repo_root)
    if layout is not None:
        return layout.git_dir
    value = _git_output(repo_root, "rev-parse", "--git-dir").strip()
    git_dir = Path(value)
    if not git_dir.is_absolute():
        git_dir = repo_root / git_dir
    resolved = git_dir.resolve()
    if not resolved.is_dir():
        raise TaskRunError(f"Git directory is not a directory: {resolved}")
    return resolved


def _validate_branch(_repo_root: Path, branch: str) -> str:
    """Named-branch spelling. Git's check-ref-format adds nothing the charset misses."""
    if (
        not branch
        or not _BRANCH_RE.fullmatch(branch)
        or ".." in branch
        or "//" in branch
        or branch.endswith((".", "/", ".lock"))
        or ".lock/" in branch
    ):
        raise TaskRunError(f"--branch is not a valid named branch: {branch!r}")
    return branch


def _is_inside(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
    except ValueError:
        return False
    return True


def _validate_worktree_path(repo_root: Path, target_path: Path) -> Path:
    target = target_path.expanduser().resolve()
    if target == repo_root or _is_inside(target, repo_root):
        raise TaskRunError(f"worktree path must be outside the repository: {target}")
    if target.exists() or target.is_symlink():
        raise TaskRunError(f"worktree path already exists: {target}")
    return target


def _parse_nul_paths(output: str) -> list[str]:
    return sorted({entry for entry in output.split("\0") if entry})


def _collect_populations(
    repo_root: Path, *, checkout: CheckoutView | None = None
) -> dict[str, list[str]]:
    """Worktree populations from the same porcelain-v2 snapshot as completion."""
    populations, _, _ = _collect_populations_with_metadata(repo_root, checkout=checkout)
    return populations


def _collect_populations_with_metadata(
    repo_root: Path, *, checkout: CheckoutView | None = None
) -> tuple[dict[str, list[str]], str | None, str | None]:
    """Read one worktree moment: dirty populations plus the checked-out HEAD."""
    try:
        moment = moment_from_status((checkout or GitCheckout(repo_root)).status(ignored=True))
    except (GitStatusError, OSError) as exc:
        raise TaskRunError(str(exc)) from exc
    return moment.populations, moment.head_oid, moment.branch


def _snapshot_payload(snapshot: Mapping[str, Sequence[str]]) -> dict[str, Any]:
    return {key: {"count": len(paths), "paths": list(paths)} for key, paths in snapshot.items()}


def _population_delta(
    before: Mapping[str, Sequence[str]],
    after: Mapping[str, Sequence[str]],
    *,
    preflight: bool = False,
) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for population in ("tracked", "untracked", "ignored"):
        before_set = set(before.get(population, ()))
        after_set = set(after.get(population, ()))
        added = sorted(after_set - before_set)
        removed = sorted(before_set - after_set)
        if preflight:
            verdict = PASS if population == "ignored" or not after_set else FAIL
            reason = (
                "ignored entries are reported as baseline residue"
                if population == "ignored"
                else "fresh worktrees must start without tracked or untracked changes"
            )
        elif population == "tracked":
            verdict, reason = PASS, "tracked changes are the task candidate and remain inspectable"
        elif population == "untracked":
            verdict = PASS
            reason = (
                "new untracked files remain candidate changes; exact scope determines whether they are allowed"
                if added
                else "no new untracked files appeared during codex exec"
            )
        else:
            verdict = "warn" if added else PASS
            reason = (
                "new ignored files appeared; inspect the generated-file causes"
                if added
                else "no new ignored files appeared during codex exec"
            )
        result[population] = {
            "before_count": len(before_set),
            "after_count": len(after_set),
            "added": added,
            "removed": removed,
            "paths": sorted(after_set),
            "verdict": verdict,
            "reason": reason,
        }
    return result


def _changed_paths(repo_root: Path, base_sha: str) -> list[str]:
    return sorted(set(_diff_paths(repo_root, base_sha)) | set(_untracked_paths(repo_root)))


def _diff_paths(repo_root: Path, *revisions: str) -> list[str]:
    return _parse_nul_paths(
        _git_output(
            repo_root,
            "diff",
            "--no-renames",
            "--name-only",
            "-z",
            *revisions,
            "--",
        )
    )


def _untracked_paths(repo_root: Path) -> list[str]:
    return _parse_nul_paths(
        _git_output(repo_root, "ls-files", "--others", "--exclude-standard", "-z", "--")
    )


def _is_ancestor(repo_root: Path, base_sha: str, head: str) -> bool:
    """True when `base_sha` is reachable from `head`, so HEAD can carry base-to-HEAD."""
    completed = run_process(
        ["git", "-C", str(repo_root), "merge-base", "--is-ancestor", base_sha, head],
        cwd=repo_root,
        timeout_seconds=None,
    )
    return completed.returncode == 0


def _base_is_fresh(repo_root: Path, base_sha: str, tip_sha: str) -> bool:
    """A base is current when it is the tip or already contains the tip."""
    return base_sha == tip_sha or _is_ancestor(repo_root, tip_sha, base_sha)


def _checkout_own_dir(create_payload: dict[str, Any]) -> Path:
    """Validate the checkout-specific Git dir carried by worktree creation."""
    checkout = create_payload.get("_checkout")
    if not isinstance(checkout, dict):
        raise TaskRunError("worktree create payload is missing checkout metadata")
    raw = checkout.get("own_dir")
    if not isinstance(raw, str) or not raw or raw != raw.strip():
        raise TaskRunError("worktree create payload has malformed checkout own_dir")
    candidate = Path(raw)
    if not candidate.is_absolute():
        raise TaskRunError("worktree create payload checkout own_dir must be absolute")
    try:
        resolved = candidate.resolve()
    except (OSError, RuntimeError, ValueError) as exc:
        raise TaskRunError("worktree create payload has unusable checkout own_dir") from exc
    if not resolved.is_dir():
        raise TaskRunError(
            f"worktree create payload checkout own_dir is not an existing directory: {resolved}"
        )
    return resolved

"""Resolve task-run shorthand and explicit preflight inputs."""

from __future__ import annotations

